#!/usr/bin/env python3
"""Source trailers and an exact non-primary pre-roll play their own generated bytes."""
import json
import os
import socketserver
import subprocess
import tempfile
import threading

import test_native_transcode as t
from test_download_queue import start_persistent


def main():
    assert t.FFMPEG and t.FFPROBE, "FFmpeg and ffprobe required"
    with tempfile.TemporaryDirectory(prefix="rex-cinema-http-") as directory:
        rows = []
        for key, name, color in (("1", "feature", "blue"), ("2", "other", "green"),
                                 ("3", "trailer", "yellow"), ("4", "preroll-primary", "green"),
                                 ("5", "preroll-selected", "red")):
            path = os.path.join(directory, name + ".mkv")
            subprocess.run([t.FFMPEG, "-v", "error", "-nostdin", "-y", "-f", "lavfi", "-i",
                "color=c=%s:s=96x54:r=24:d=4" % color, "-f", "lavfi", "-i", "sine=frequency=440:duration=4",
                "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "-c:a", "aac", path],
                check=True, capture_output=True, timeout=30)
            t.MEDIA[name + ".mkv"] = path
            row = t.row(key, name, name + ".mkv", t.probe(path)["streams"], os.path.getsize(path), 4)
            row["Media"][0].update(width=96, height=54, videoResolution="sd")
            row["Media"][0]["Part"][0]["Stream"][0].update(width=96, height=54)
            rows.append(row)
        rows[2].update(type="clip", extraType=1, subtype="trailer", index=1,
                       _parentRatingKey="2", _librarySectionID=1)
        rows[2].pop("librarySectionID")
        selected = rows.pop()["Media"][0]
        selected_file = selected["Part"][0]["file"]
        rows[3]["Media"].append(selected)
        machine = "a" * 40
        catalog = os.path.join(directory, "catalog.json")
        with open(catalog, "w") as out:
            json.dump({"machineIdentifier": machine, "sections": [
                {"key": "1", "type": "movie", "title": "Source cinema", "uuid": "cinema-http"}],
                "items": rows}, out)
        with socketserver.ThreadingTCPServer(("127.0.0.1", t.free_port()), t.Zurg) as source:
            source.daemon_threads = True
            threading.Thread(target=source.serve_forever, daemon=True).start()
            port, process, _ = start_persistent(catalog, source.server_address[1], directory)
            try:
                t.get(port, "/:/prefs", [("CinemaTrailersFromLibrary", "1"),
                    ("CinemaTrailersType", "0"), ("CinemaTrailersPrerollID", selected_file)], method="PUT")
                query = [("type", "video"), ("extrasPrefixCount", "1"), ("shuffle", "0"),
                         ("uri", "server://%s/com.plexapp.plugins.library/library/metadata/1" % machine)]
                status, _, raw = t.get(port, "/playQueues", query, method="POST")
                assert status == 200, (status, raw)
                queue = json.loads(raw)["MediaContainer"]
                assert [str(row["ratingKey"]) for row in queue["Metadata"]] == ["3", "4", "1"], queue
                assert str(queue["playQueueSelectedMetadataItemID"]) == "1"
                queue_id = queue["playQueueID"]

                def verify_rows(current_port, metadata):
                    for item, expected in zip(metadata, ("yellow", "red", "blue")):
                        key = str(item["ratingKey"])
                        playback = t.plex_web_query(key, "cinema-" + key, directPlay="1", partIndex="0",
                            mediaIndex="0", maxVideoBitrate="12000", playQueueID=str(queue_id),
                            playQueueItemID=str(item["playQueueItemID"]))
                        status, _, answer = t.get(current_port, "/video/:/transcode/universal/decision", playback)
                        assert status == 200, (status, answer)
                        media = json.loads(answer)["MediaContainer"]["Metadata"][0]["Media"][0]
                        part = media["Part"][0]
                        status, _, body = t.get(current_port, part["key"])
                        assert status == 200, (status, part)
                        clip = os.path.join(directory, "received-" + key + ".mkv")
                        with open(clip, "wb") as out:
                            out.write(body)
                        pixel = subprocess.run([t.FFMPEG, "-v", "error", "-i", clip, "-frames:v", "1",
                            "-vf", "scale=1:1", "-pix_fmt", "rgb24", "-f", "rawvideo", "-"],
                            check=True, capture_output=True, timeout=30).stdout
                        r, g, b = pixel
                        correct = {"yellow": r > 180 and g > 180 and b < 50,
                                   "red": r > 180 and g < 50 and b < 50,
                                   "blue": b > 180 and r < 50 and g < 50}[expected]
                        assert correct, ("wrong cinema bytes", key, expected, list(pixel), part.get("file"))
                verify_rows(port, queue["Metadata"])
                process.terminate()
                process.wait(timeout=30)
                port, process, _ = start_persistent(catalog, source.server_address[1], directory)
                status, _, raw = t.get(port, "/playQueues/" + str(queue_id))
                assert status == 200, (status, raw)
                restored = json.loads(raw)["MediaContainer"]["Metadata"]
                verify_rows(port, restored)
                t.get(port, "/:/prefs", [("CinemaTrailersPrerollID", "/not-a-registered-part.mkv")], method="PUT")
                assert t.get(port, "/playQueues", query, method="POST")[0] == 409
            finally:
                process.terminate()
                process.wait(timeout=30)
                source.shutdown()
    print("PASS cinema HTTP: trailer, exact secondary pre-roll and feature decoded correctly before/after restart")


if __name__ == "__main__":
    main()
